mask = set()
pend = []
tr = []
dep = [0, 0]
def deliver():
    while True:
        r = [y for y in pend if y not in mask]
        if not r:
            return
        y = min(r)
        pend.remove(y)
        rais(y)
def rais(s):
    if s in mask:
        if s not in pend:
            pend.append(s)
    elif s in H:
        saved = set(mask)
        mask.add(s)
        tr.append(str(s))
        dep[0] += 1
        dep[1] = max(dep[1], dep[0])
        for t in H[s]:
            rais(t)
        mask.clear()
        mask.update(saved)
        dep[0] -= 1
        deliver()
