vals = {}
flag = {}
seen = []
shown = []
q = int(input())
live = True
for _ in range(q):
    a = input().split()
    if not live:
        continue
    c = a[0]
    if c == "set":
        vals[a[1]] = a[2]
        flag.setdefault(a[1], False)
    elif c == "export":
        if len(a) > 2:
            vals[a[1]] = a[2]
        flag[a[1]] = True
    elif c == "unset":
        vals.pop(a[1], None)
        flag.pop(a[1], None)
    elif c == "echo":
        shown.append(vals.get(a[1], ""))
    else:
        seen.append(sum(1 for k in vals if flag.get(k)))
        if c == "exec":
            live = False
print(*seen)

